-- Step 17.14: read-governed Data & Business Analyst Agent.
create table public.analyst_agent_jobs(id uuid primary key default gen_random_uuid(),job_ref text not null unique,analysis_type text not null check(analysis_type in('business','revenue','user','marketing','risk','forecast')),title text not null,dataset_refs text[] not null default '{}',metric_definitions jsonb not null default '{}' check(jsonb_typeof(metric_definitions)='object'),assumptions jsonb not null default '{}' check(jsonb_typeof(assumptions)='object'),status text not null default 'queued' check(status in('queued','running','waiting_data','waiting_human','completed','failed','cancelled')),created_by uuid not null default auth.uid() references auth.users(id) on delete restrict,created_at timestamptz not null default statement_timestamp(),updated_at timestamptz not null default statement_timestamp());create index analyst_jobs_queue_idx on public.analyst_agent_jobs(status,created_at);
create table public.analyst_agent_reports(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.analyst_agent_jobs(id) on delete restrict,report_type text not null check(report_type in('dashboard','analysis','forecast','anomaly','executive')),summary jsonb not null default '{}' check(jsonb_typeof(summary)='object'),lineage jsonb not null default '{}' check(jsonb_typeof(lineage)='object'),uncertainty jsonb not null default '{}' check(jsonb_typeof(uncertainty)='object'),status text not null default 'draft' check(status in('draft','review','approved','delivered','superseded')),created_at timestamptz not null default statement_timestamp());create index analyst_reports_job_idx on public.analyst_agent_reports(job_id,created_at desc);
create table public.analyst_agent_approvals(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.analyst_agent_reports(id) on delete restrict,approval_type text not null check(approval_type in('metric_definition','dashboard_publish','executive_delivery','sensitive_export')),status text not null default 'pending' check(status in('pending','approved','rejected','cancelled')),requested_by uuid not null default auth.uid() references auth.users(id),decided_by uuid references auth.users(id),decision_reason text,requested_at timestamptz not null default statement_timestamp(),decided_at timestamptz,check((status='pending'and decided_by is null and decided_at is null)or(status<>'pending'and decided_by is not null and decided_at is not null)));
create table public.analyst_agent_automations(id uuid primary key default gen_random_uuid(),automation_key text not null unique,name text not null,configuration jsonb not null default '{}' check(jsonb_typeof(configuration)='object'),status text not null default 'draft' check(status in('draft','active','paused','archived')),source_data_mutation boolean not null default false check(not source_data_mutation),ledger_mutation boolean not null default false check(not ledger_mutation),budget_mutation boolean not null default false check(not budget_mutation),risk_decision_mutation boolean not null default false check(not risk_decision_mutation),created_by uuid not null default auth.uid() references auth.users(id),approved_by uuid references auth.users(id),approved_at timestamptz,check(status<>'active'or(approved_by is not null and approved_at is not null)));
create table private.analyst_agent_activity(id bigint generated always as identity primary key,job_id uuid references public.analyst_agent_jobs(id) on delete set null,actor_type public.audit_actor_type not null,actor_id uuid references auth.users(id) on delete set null,action text not null,evidence jsonb not null default '{}' check(jsonb_typeof(evidence)='object'),occurred_at timestamptz not null default statement_timestamp());create index analyst_activity_timeline_idx on private.analyst_agent_activity(occurred_at desc,id desc);
alter table public.analyst_agent_jobs enable row level security;alter table public.analyst_agent_jobs force row level security;alter table public.analyst_agent_reports enable row level security;alter table public.analyst_agent_reports force row level security;alter table public.analyst_agent_approvals enable row level security;alter table public.analyst_agent_approvals force row level security;alter table public.analyst_agent_automations enable row level security;alter table public.analyst_agent_automations force row level security;alter table private.analyst_agent_activity enable row level security;alter table private.analyst_agent_activity force row level security;
revoke all on public.analyst_agent_jobs,public.analyst_agent_reports,public.analyst_agent_approvals,public.analyst_agent_automations from public,anon,authenticated;revoke all on private.analyst_agent_activity from public,anon,authenticated,service_role;grant select,insert,update on public.analyst_agent_jobs,public.analyst_agent_approvals,public.analyst_agent_automations to authenticated;grant select on public.analyst_agent_reports to authenticated;
create function private.is_step_17_14_analyst_admin(p_owner_only boolean default false)returns boolean language sql stable security definer set search_path='' as $$select(select auth.jwt()->>'aal')='aal2'and exists(select 1 from public.user_roles r where r.user_id=(select auth.uid())and r.is_active and r.revoked_at is null and(r.role='owner'::public.app_role or(not p_owner_only and r.role='analyst'::public.app_role)));$$;revoke all on function private.is_step_17_14_analyst_admin(boolean) from public,anon,authenticated,service_role;grant execute on function private.is_step_17_14_analyst_admin(boolean) to authenticated;
create policy analyst_jobs_read on public.analyst_agent_jobs for select to authenticated using((select private.is_step_17_14_analyst_admin(false)));create policy analyst_jobs_write on public.analyst_agent_jobs for all to authenticated using((select private.is_step_17_14_analyst_admin(false)))with check(created_by=(select auth.uid())and(select private.is_step_17_14_analyst_admin(false)));create policy analyst_reports_read on public.analyst_agent_reports for select to authenticated using((select private.is_step_17_14_analyst_admin(false)));create policy analyst_approvals_read on public.analyst_agent_approvals for select to authenticated using((select private.is_step_17_14_analyst_admin(false)));create policy analyst_approvals_request on public.analyst_agent_approvals for insert to authenticated with check(requested_by=(select auth.uid())and status='pending'and(select private.is_step_17_14_analyst_admin(false)));create policy analyst_approvals_decide on public.analyst_agent_approvals for update to authenticated using((select private.is_step_17_14_analyst_admin(true)))with check(decided_by=(select auth.uid())and(select private.is_step_17_14_analyst_admin(true)));create policy analyst_automations_read on public.analyst_agent_automations for select to authenticated using((select private.is_step_17_14_analyst_admin(false)));create policy analyst_automations_write on public.analyst_agent_automations for all to authenticated using((select private.is_step_17_14_analyst_admin(true)))with check(created_by=(select auth.uid())and not source_data_mutation and not ledger_mutation and not budget_mutation and not risk_decision_mutation and(select private.is_step_17_14_analyst_admin(true)));create policy analyst_activity_deny on private.analyst_agent_activity as restrictive for all to anon,authenticated using(false)with check(false);
create function private.reject_analyst_activity_mutation()returns trigger language plpgsql security definer set search_path='' as $$begin raise exception 'analyst activity is append-only';end;$$;revoke all on function private.reject_analyst_activity_mutation() from public,anon,authenticated,service_role;create trigger analyst_activity_immutable before update or delete on private.analyst_agent_activity for each row execute function private.reject_analyst_activity_mutation();
